// Twelve shared DILR sets. Every question retains its complete data when opened alone.
function addSet(id,title,passage,topic,items,difficulty='Intermediate'){items.forEach(([text,options,answer,explanation])=>addMC('dilr',topic,text,options,answer,explanation,{group:id,groupTitle:title,passage,difficulty}))}
